```csharp
using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _sut;

    public OrderServiceTests()
    {
        _sut = new OrderService();
    }

    private static List<OrderItem> CreateItems(decimal price = 10m, int quantity = 2) =>
    [
        new OrderItem { ProductName = "Widget", Price = price, Quantity = quantity }
    ];

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectTotal()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "A", Price = 25m, Quantity = 2 },
            new() { ProductName = "B", Price = 10m, Quantity = 1 },
        };

        // Act
        var order = _sut.CreateOrder("cust-1", items);

        // Assert
        Assert.AreEqual(60m, order.Total);
        Assert.AreEqual("cust-1", order.CustomerId);
        Assert.IsNotNull(order.Id);
        Assert.HasCount(2, order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithNullCustomerId_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder(null!, CreateItems()));

        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithNullItems_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder("cust-1", null!));

        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithEmptyItems_ThrowsInvalidOperationException()
    {
        Assert.ThrowsExactly<InvalidOperationException>(
            () => _sut.CreateOrder("cust-1", []));
    }

    [TestMethod]
    public void GetOrder_ExistingOrder_ReturnsOrder()
    {
        // Arrange
        var created = _sut.CreateOrder("cust-1", CreateItems());

        // Act
        var found = _sut.GetOrder(created.Id);

        // Assert
        Assert.AreSame(created, found);
    }

    [TestMethod]
    public void GetOrder_NonExistentId_ReturnsNull()
    {
        Assert.IsNull(_sut.GetOrder("does-not-exist"));
    }

    [TestMethod]
    public void GetOrdersByCustomer_ReturnsOnlyMatchingOrders()
    {
        // Arrange
        _sut.CreateOrder("cust-1", CreateItems());
        _sut.CreateOrder("cust-1", CreateItems());
        _sut.CreateOrder("cust-2", CreateItems());

        // Act
        var results = _sut.GetOrdersByCustomer("cust-1");

        // Assert
        Assert.HasCount(2, results);
    }

    [TestMethod]
    public void GetOrdersByCustomer_NoMatches_ReturnsEmptyList()
    {
        Assert.IsEmpty(_sut.GetOrdersByCustomer("unknown"));
    }

    [TestMethod]
    [DataRow(5, 3, 15)]
    [DataRow(10, 1, 10)]
    [DataRow(0, 5, 0, DisplayName = "Free item")]
    public void CreateOrder_SingleItem_CalculatesTotalCorrectly(
        double price, int quantity, double expectedTotal)
    {
        var items = CreateItems((decimal)price, quantity);

        var order = _sut.CreateOrder("cust-1", items);

        Assert.AreEqual((decimal)expectedTotal, order.Total);
    }
}
```

**Key practices applied:**

- **`sealed` test class** — better performance, signals no inheritance
- **`Assert.ThrowsExactly<T>`** — matches only the exact exception type
- **Specific assertions** — `Assert.HasCount`, `Assert.IsEmpty`, `Assert.AreSame`, `Assert.IsNull` instead of generic `Assert.IsTrue`
- **AAA pattern** with clear sections
- **`[DataRow]`** for parameterized total calculation scenarios
- **Constructor initialization** with `readonly` field for the system under test

